package com.nequard.monitoring;
import com.nequard.network.Device;import com.nequard.network.DeviceRepository;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.time.Instant;
@Service public class MonitoringEngine{private final DeviceRepository devices;private final MetricSnapshotRepository metrics;public MonitoringEngine(DeviceRepository d,MetricSnapshotRepository m){devices=d;metrics=m;}@Scheduled(fixedDelayString="${nequard.monitoring.interval-ms:30000}")public void collect(){for(Device d:devices.findAll()){MetricSnapshot m=new MetricSnapshot();m.setDeviceId(d.getId());m.setRecordedAt(Instant.now());m.setCpuPercent(d.getCpuPercent());m.setMemoryPercent(d.getMemoryPercent());m.setStatus(d.getOperationalStatus());metrics.save(m);}}}